.no-sub-careers-view {
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);
  .no-corner-btn {
    @include flex-center();
  }
  &__inner {
    display: grid;
    grid-template-columns: 8fr 4fr;
    gap: var(--gutter-md);
    @include mq(md) {
      grid-template-columns: 1fr;
    }
  }
  &__wrap {
    display: flex;
    flex-direction: column;
  }
  &__title {
    padding-bottom: var(--gutter-sm);
    border-bottom: 1px solid var(--clr-border-default);
    margin-top: var(--gutter-md);
    h2 {
    }
  }

  &__map {
    iframe {
      width: 100%;
      border: 0;
      display: block;
      aspect-ratio: 16/9;
    }
  }
  &__content {
    margin-top: var(--gutter-md);
  }
  &__info {
    display: flex;
    flex-direction: column;
    gap: var(--gutter-md);
    &-card {
      border: 1px solid var(--clr-border-default);
      padding: var(--gutter-sm);
    }
    &-item {
      display: flex;
      align-items: center;
      gap: var(--gutter-xs);
      padding: var(--gutter-xs) 0;
      border-bottom: 1px solid var(--clr-border-default);
      span {
        color: var(--clr-text-body);
